SCHEMA_ENTITY_TYPES = {"organization", "product"}
SCHEMA_RELATIONS = {"supplies", "produces"}

def build_graph():
    return {"nodes": {}, "edges": []}

def insert_triple(graph, subject, subject_type, relation, obj, obj_type, source_date):
    # validate against the schema
    if subject_type not in SCHEMA_ENTITY_TYPES or obj_type not in SCHEMA_ENTITY_TYPES:
        return "Rejected: entity type not in schema"
    if relation not in SCHEMA_RELATIONS:
        return "Rejected: relation type not in schema"

    # deduplicate entities on insertion
    graph["nodes"].setdefault(subject, subject_type)
    graph["nodes"].setdefault(obj, obj_type)

    # resolve conflicting edges by preferring the most recent source
    for edge in graph["edges"]:
        if edge["subject"] == subject and edge["relation"] == relation:
            if source_date > edge["source_date"]:
                edge["object"] = obj
                edge["source_date"] = source_date
            return "Resolved conflicting edge, kept most recent"

    graph["edges"].append({"subject": subject, "relation": relation, "object": obj, "source_date": source_date})
    return "Inserted"

graph = build_graph()
print(insert_triple(graph, "Falcon Cloud", "organization", "supplies", "Acme Corp", "organization", "2026-01-01"))
print(insert_triple(graph, "Falcon Cloud", "organization", "supplies", "Beta Inc", "organization", "2026-06-01"))
print("\nFinal graph:")
print(graph)
